package com.dixitdada.journalApp.config; import org.springframework.context.annotation.*; import org.springframework.data.redis.connection.RedisConnectionFactory; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.data.redis.serializer.StringRedisSerializer; @Configuration public class RedisConfig { @Bean RedisTemplate<String,String> redisTemplate(RedisConnectionFactory f){RedisTemplate<String,String> t=new RedisTemplate<>();t.setConnectionFactory(f);t.setKeySerializer(new StringRedisSerializer());t.setValueSerializer(new StringRedisSerializer());return t;} }